#pragma once

#include <array>
#include <cstddef>
#include <cstdint>

/**
 * The many statements throughput benchmarks, built with BENCH_MANY_STATEMENTS, log 256 distinct
 * statements of one to five mixed arguments instead of cycling between five, in the order below.
 * The statements are in many_statements/, generated by tools/gen_many_statements.py: one file per
 * call style, all writing the same messages.
 */
inline char const* const bench_symbols[8] = {"AAPL", "MSFT", "ES", "NQ", "CL", "ZN", "GC", "EURUSD"};

/**
 * The statement logged by each iteration, a fixed pseudo-random order computed before timing starts
 */
inline std::array<uint8_t, 65536> const bench_statement_order = []()
{
  std::array<uint8_t, 65536> order{};
  uint32_t state{2463534242u};
  for (uint8_t& statement : order)
  {
    state ^= state << 13;
    state ^= state >> 17;
    state ^= state << 5;
    statement = static_cast<uint8_t>(state % 256);
  }
  return order;
}();
